-- Scenario: SQLite-specific syntax and functions
SELECT * FROM files WHERE path GLOB '*.txt';
SELECT * FROM files WHERE path NOT GLOB '[a-c]*';
SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%';
SELECT name, sql FROM sqlite_schema WHERE type IN ('table', 'index');
SELECT typeof(x), quote(x), hex(x), zeroblob(16), randomblob(8) FROM t;
SELECT ifnull(a, 0), nullif(a, ''), coalesce(a, b, 'n/a') FROM t;
SELECT iif(a > 1, 'big', 'small') FROM t;
SELECT CASE WHEN a > 1 THEN 'x' WHEN a = 1 THEN 'y' ELSE 'z' END FROM t;
SELECT CASE a WHEN 1 THEN 'one' WHEN 2 THEN 'two' END FROM t;
SELECT a FROM t WHERE a IS NOT b;
SELECT a FROM t WHERE a IS b;
SELECT a FROM t WHERE a IS DISTINCT FROM b;
SELECT a FROM t WHERE a IS NOT DISTINCT FROM b;
SELECT a FROM t WHERE a BETWEEN 1 AND 10 AND b NOT BETWEEN 2 AND 3;
SELECT a FROM t WHERE a ISNULL;
SELECT a FROM t WHERE a NOTNULL;
SELECT a FROM t WHERE a == 1 OR a != 2 OR a <> 3;
SELECT 'it''s' AS s, x'DEADBEEF' AS b, 0xFF AS h, 1e3 AS f;
SELECT "quoted col", [bracket col], `backtick col` FROM "my table";
SELECT a || b || c FROM t;
SELECT a & b, a | b, ~a, a << 2, a >> 1, a % 3 FROM t;
SELECT CAST(a AS INTEGER), CAST(b AS TEXT), CAST(c AS REAL), CAST(d AS NUMERIC), CAST(e AS BLOB) FROM t;
SELECT a REGEXP '^foo' FROM t;
SELECT a COLLATE NOCASE FROM t ORDER BY a COLLATE BINARY;
SELECT a FROM t ORDER BY a NULLS LAST;
SELECT a FROM t ORDER BY a DESC NULLS FIRST, b ASC;
SELECT a FROM t LIMIT 10, 20;
SELECT a FROM t LIMIT -1 OFFSET 5;
SELECT DISTINCT a FROM t;
SELECT ALL a FROM t;
SELECT a FROM t INDEXED BY idx_a WHERE a = 1;
SELECT a FROM t NOT INDEXED;
SELECT * FROM t1 NATURAL JOIN t2;
SELECT * FROM t1 JOIN t2 USING (id);
SELECT * FROM t1 CROSS JOIN t2;
SELECT * FROM t1, t2 WHERE t1.id = t2.id;
SELECT * FROM t1 LEFT OUTER JOIN t2 ON t1.id = t2.id;
SELECT * FROM t1 NATURAL LEFT JOIN t2;
SELECT * FROM t1 RIGHT JOIN t2 ON t1.id = t2.id;
SELECT * FROM t1 FULL OUTER JOIN t2 ON t1.id = t2.id;
SELECT * FROM main.t1;
SELECT * FROM (SELECT 1 AS a UNION ALL SELECT 2 UNION SELECT 3 INTERSECT SELECT 3 EXCEPT SELECT 2);
VALUES (1, 'a'), (2, 'b');
SELECT * FROM pragma_table_info('users');
SELECT * FROM generate_series(1, 10);
SELECT sqlite_version(), sqlite_source_id();
SELECT unixepoch(), unixepoch('now', 'start of day');
SELECT date('now'), time('now'), datetime('now', 'localtime'), julianday('now');
SELECT datetime('now', '+1 day', 'start of month', '-1 second');
SELECT strftime('%Y-%m-%dT%H:%M:%fZ', 'now');
SELECT datetime(created_at, 'unixepoch') FROM events;
SELECT timediff('2024-01-02', '2024-01-01');
SELECT abs(-1), round(3.14159, 2), max(1, 2, 3), min(1, 2), length('abc'), substr('hello', 2, 3), upper('a'), lower('A'), trim('  x '), ltrim('x', 'x'), replace('abc', 'b', 'X'), instr('abc', 'b'), printf('%05.1f', 3.14159), format('%d', 5);
SELECT unhex('4142'), likely(a), unlikely(a), likelihood(a, 0.5) FROM t;
SELECT random(), abs(random()) % 100;
SELECT a FROM t WHERE rowid = 5;
SELECT rowid, _rowid_, oid, * FROM t;
SELECT a FROM t WHERE (a, b) IN (SELECT a, b FROM u);
SELECT (1, 2) = (1, 2);
SELECT a FROM t WHERE a IN ();
SELECT a FROM t WHERE a IN (1, 2, 3) AND b NOT IN (SELECT id FROM u);
SELECT a FROM t WHERE a IN u;
SELECT * FROM t WHERE NOT EXISTS (SELECT 1 FROM u WHERE u.id = t.id);
SELECT (SELECT max(id) FROM u) AS mx, a FROM t;
SELECT a FROM t WHERE a LIKE 'x%' OR a NOT LIKE 'y_';
SELECT a FROM t WHERE a MATCH 'foo';
SELECT -a, +a, NOT a FROM t;
SELECT a FROM t GROUP BY a HAVING count(*) > 1;
SELECT a, count(*) AS c FROM t GROUP BY 1 ORDER BY 2 DESC;
